      C("Despite ___ hard, he failed the exam.", ["studying", "he studied", "study"], "studying", "Despite + -ing.", tp="contrast"),
      W(["Despite", "Although", "whereas", "In spite of"], ["___ the cold, we swam.", "___ it was cold, we swam.", "I like summer, ___ she likes winter.", "___ having little money, they were happy."], ["Despite", "Although", "whereas", "In spite of"],
        "Іменник / речення / порівняння.", "Существительное / предложение / сравнение.", reuse=False, tp="contrast"),
      X("Despite it was late, we stayed.", "Although it was late, we stayed.", "Речення → although.", "Предложение → although.", acc=["Despite the late hour, we stayed.", "Despite it being late, we stayed."], tp="contrast"),
      X("In spite of the rain, but we went out.", "In spite of the rain, we went out.", "Без but.", tp="contrast"),
